WIKI_CACHE={}
PERSON_CONTEXT=re.compile(r"(영화\\s*감독|감독|영화인|filmmaker|film director|screenwriter|producer|cinema)",re.I)

def _norm_person(value):
    return re.sub(r"[^0-9a-z가-힣]+","",(value or "").casefold())

def _wiki_title_matches(name,title):
    target=_norm_person(name); candidate=_norm_person(title)
    if target and target==candidate:return True
    parts=[x for x in re.findall(r"[0-9A-Za-z가-힣]+",name or "") if len(x)>1]
    return len(parts)>=2 and all(_norm_person(x) in candidate for x in parts)

def wikimedia_person(name):
    if not name:return None
    if name in WIKI_CACHE:return WIKI_CACHE[name]
    try:
        search=get_json("https://ko.wikipedia.org/w/api.php?"+urlencode({
            "action":"query","list":"search","srsearch":name+" 영화 감독","format":"json","utf8":1,"srlimit":8
        }))
        for hit in search.get("query",{}).get("search",[]):
            title=hit.get("title","")
            if not _wiki_title_matches(name,title):continue
            summary=get_json("https://ko.wikipedia.org/api/rest_v1/page/summary/"+quote(title))
            desc=summary.get("description","") or ""
            extract=summary.get("extract","") or ""
            if summary.get("type")=="disambiguation" or "동음이의어" in (desc+" "+extract):continue
            if not PERSON_CONTEXT.search(desc+" "+extract):continue
            item={
                "title":summary.get("title",title),
                "description":desc,
                "extract":extract,
                "url":summary.get("content_urls",{}).get("desktop",{}).get("page","")
            }
            WIKI_CACHE[name]=item
            return item
    except Exception:
        pass
    WIKI_CACHE[name]=None
    return None

