def classify_local_art(x,prev):
    if x.get("category")!="지역 예술":return None
    text=" ".join(str(x.get(k) or "") for k in ("titleOriginal","descriptionOriginal","source")).lower()
    scored=[]
    for cat,words in ART_KEYWORDS.items():
        score=sum(1 for word in words if word.lower() in text)
        if score:scored.append((score,cat))
    if scored:
        scored.sort(reverse=True)
        if len(scored)==1 or scored[0][0]>scored[1][0]:return scored[0][1]
    return prev.get("localArtsType")

